values ('c0160031-0301-4000-8000-000000000001', 'Humilde y Fervorosa Hermandad de Nuestro Padre Jesús Cautivo, Nuestra Señora del Dulce Nombre de María, San Lucas Evangelista y Santa Ángela de la Cruz', 'Jesús Cautivo', 'Origen vecinal desde 1973; agrupación de fieles en los años 80; Hermandad de Penitencia desde el 28 de febrero de 1990.', 'fe884314-1f8b-4566-8bb9-7b11ecf42446', 'c0160031-0201-4000-8000-000000000001', null, null, null, null, ARRAY['Penitencia']::text[], 'Lunes Santo', 'Cierre municipal HC-016 de Coria del Río; solo se publican datos con Fuente suficiente.', 'La devoción al antiguo Nazareno se arraigó en el barrio de la Blanca Paloma desde 1973. La corporación fue aprobada como Hermandad de Penitencia en 1990 y realiza su estación el Lunes Santo.') on conflict ("entity_id") do update set "official_name" = excluded."official_name", "popular_name" = excluded."popular_name", "foundation_text" = excluded."foundation_text", "municipality_id" = excluded."municipality_id", "canonical_see_place_id" = excluded."canonical_see_place_id", "neighborhood" = excluded."neighborhood", "website_url" = excluded."website_url", "instagram_url" = excluded."instagram_url", "crest_path" = excluded."crest_path", "brotherhood_types" = excluded."brotherhood_types", "current_procession_day" = excluded."current_procession_day", "notes" = excluded."notes", "history_text" = excluded."history_text";

