values ('c0160031-0302-4000-8000-000000000002', 'Hermandad Sacramental y Cofradía de Nazarenos de Nuestro Padre Jesús de la Paz en su Presentación al Pueblo, María Santísima de Gracia y Esperanza, Piedad del Santísimo Cristo de la Misericordia, Nuestra Señora de los Dolores, San Juan Evangelista y Patriarca Bendito Señor San José', 'Hermandad de San José', 'Fraternidad Cristiana desde 1990; Hermandad de Penitencia desde 2007; Piedad incorporada como titular en 2015 y primera estación de Sábado Santo en 2018.', 'fe884314-1f8b-4566-8bb9-7b11ecf42446', 'c0160031-0202-4000-8000-000000000002', null, null, null, null, ARRAY['Sacramental', 'Penitencia']::text[], 'Martes Santo · Sábado Santo', 'Cierre municipal HC-016 de Coria del Río; solo se publican datos con Fuente suficiente.', 'Nacida en torno a la Parroquia de San José, articula la estación del Martes Santo y, dentro de la misma corporación, la Piedad del Sábado Santo. No se crea una hermandad independiente para la Piedad.') on conflict ("entity_id") do update set "official_name" = excluded."official_name", "popular_name" = excluded."popular_name", "foundation_text" = excluded."foundation_text", "municipality_id" = excluded."municipality_id", "canonical_see_place_id" = excluded."canonical_see_place_id", "neighborhood" = excluded."neighborhood", "website_url" = excluded."website_url", "instagram_url" = excluded."instagram_url", "crest_path" = excluded."crest_path", "brotherhood_types" = excluded."brotherhood_types", "current_procession_day" = excluded."current_procession_day", "notes" = excluded."notes", "history_text" = excluded."history_text";

