values ('c0160031-0303-4000-8000-000000000003', 'Antigua Hermandad de Jesús Nazareno y Cofradía de Marineros, Fervorosa Hermandad de Nuestro Padre Jesús del Gran Poder y Nuestra Señora del Carmen', 'Gran Poder y Carmen', 'Cofradía carmelitana documentada desde 1603 y antigua Hermandad de Jesús Nazareno; configuración actual fruto de su evolución histórica.', 'fe884314-1f8b-4566-8bb9-7b11ecf42446', '5317981f-4be1-4bbd-a4c8-943d178d247e', null, null, null, null, ARRAY['Penitencia', 'Gloria']::text[], 'Miércoles Santo', 'Cierre municipal HC-016 de Coria del Río; solo se publican datos con Fuente suficiente.', 'La corporación reúne en una misma identidad al Gran Poder y a Nuestra Señora del Carmen. Realiza estación penitencial el Miércoles Santo y conserva su dimensión marinera y carmelitana.') on conflict ("entity_id") do update set "official_name" = excluded."official_name", "popular_name" = excluded."popular_name", "foundation_text" = excluded."foundation_text", "municipality_id" = excluded."municipality_id", "canonical_see_place_id" = excluded."canonical_see_place_id", "neighborhood" = excluded."neighborhood", "website_url" = excluded."website_url", "instagram_url" = excluded."instagram_url", "crest_path" = excluded."crest_path", "brotherhood_types" = excluded."brotherhood_types", "current_procession_day" = excluded."current_procession_day", "notes" = excluded."notes", "history_text" = excluded."history_text";

