values ('c0160031-0306-4000-8000-000000000006', 'Real, Imperial, Ilustre y Antigua Hermandad de Nuestra Señora del Rocío de Coria del Río', 'Rocío de Coria del Río', '21 de abril de 1849; acogida como filial por la Hermandad Matriz en mayo de 1849.', 'fe884314-1f8b-4566-8bb9-7b11ecf42446', 'c0160031-0204-4000-8000-000000000004', null, null, null, null, ARRAY['Gloria']::text[], 'Romería del Rocío', 'Cierre municipal HC-016 de Coria del Río; solo se publican datos con Fuente suficiente.', 'Fundada en 1849, realiza su camino anual a la aldea del Rocío. El cierre municipal no fuerza una imagen devocional física ni un paso cuando la representación corporativa se articula mediante Simpecado.') on conflict ("entity_id") do update set "official_name" = excluded."official_name", "popular_name" = excluded."popular_name", "foundation_text" = excluded."foundation_text", "municipality_id" = excluded."municipality_id", "canonical_see_place_id" = excluded."canonical_see_place_id", "neighborhood" = excluded."neighborhood", "website_url" = excluded."website_url", "instagram_url" = excluded."instagram_url", "crest_path" = excluded."crest_path", "brotherhood_types" = excluded."brotherhood_types", "current_procession_day" = excluded."current_procession_day", "notes" = excluded."notes", "history_text" = excluded."history_text";

